package javaprojects;

import java.util.Scanner;

public class App {

    public static void main(String[] args) {

        Scanner scanner = new Scanner(System.in);
        PWCRecursion calculator = new PWCRecursion();

        System.out.println("Triangular Calculator");

        System.out.print("Enter the first number: ");
        int n = scanner.nextInt();

        System.out.print("Enter the second number: ");
        int m = scanner.nextInt();

        if (n < 0 || m < 0) {
            System.out.println("Ivalid. Numbers cannot be negative.");
        } else {
            
            System.out.println("Triangular number of " + n + ": "
                    + calculator.value(n));

            System.out.println("Triangular number of " + m + ": "
                    + calculator.value(m));

            System.out.println("Addition: " + calculator.add(n, m));

            System.out.println("Subtraction: " + calculator.subtract(n, m));
        }

        scanner.close();

    }
}